python3 - "$DEV_GRAPH_PLUGIN" "$DEV_GRAPH_ROOT" <<'PY'
import hashlib, json, shutil, sys
from pathlib import Path
plugin, root = Path(sys.argv[1]), Path(sys.argv[2])
src = plugin / "templates"
dst = root / ".dev-graph" / "templates"
contract = json.loads((src / "template-contract.json").read_text(encoding="utf-8"))
created, preserved, migration_preview = [], [], []
for f in sorted(src.iterdir()):
    if not f.is_file():
        continue
    t = dst / f.name
    if not t.exists():
        shutil.copy2(f, t)
        created.append(f.name)
    else:
        a = hashlib.sha256(f.read_bytes()).hexdigest()
        b = hashlib.sha256(t.read_bytes()).hexdigest()
        if a == b:
            preserved.append(f.name)
        else:
            migration_preview.append({"file": f.name, "plugin_digest": "sha256:"+a, "repo_digest": "sha256:"+b, "action": "preserved_user_edit"})
# contract enumerated assets missing check
enumerated = set()
enumerated.add(contract["common_frontmatter"]["template"])
for kind, spec in contract.get("artifacts", {}).items():
    if isinstance(spec, dict):
        if "template" in spec: enumerated.add(spec["template"])
        for v in (spec.get("conditional_templates") or {}).values(): enumerated.add(v)
        for st in (spec.get("subtypes") or {}).values():
            if isinstance(st, dict) and "template" in st: enumerated.add(st["template"])
            elif isinstance(st, str): enumerated.add(st)
missing = sorted(n for n in enumerated if not (dst / n).exists())
print(json.dumps({"created": created, "preserved_same_digest": preserved,
                  "migration_preview": migration_preview,
                  "contract_enumerated": sorted(enumerated),
                  "contract_missing": missing,
                  "total_files_in_templates_root": len(list(dst.iterdir()))}, ensure_ascii=False, indent=2))
PY
